toolScript:
import {
            PoseLandmarker,
            FilesetResolver
        } from "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3";
        const video = document.getElementById('scanner-video');
        const canvas = document.getElementById('overlay-canvas');
        const ctx = canvas.getContext('2d');
        const statusText = document.getElementById('status-text');
        const faceGuide = document.getElementById('face-guide');
        const resultBadge = document.getElementById('posture-result');
        const liveIndicator = document.getElementById('live-indicator');
        const calibrateBtn = document.getElementById('calibrate-btn');
        const alertOverlay = document.getElementById('alert-overlay');
        const timerDisplay = document.getElementById('timer-display');
        const graphStat = document.getElementById('graph-stat');
        const chartContainer = document.getElementById('quality-chart');
        const highScoreDisplay = document.getElementById('high-score-display');
        // Audio UI
        const audioToggleBtn = document.getElementById('audio-toggle');
        const audioKnob = document.getElementById('audio-knob');
        let poseLandmarker;
        let runningMode = "VIDEO";
        let stream = null;
        let lastVideoTime = -1;
        let results = undefined;
        let trackingActive = false;
        // Calibration Data
        let baseline = null; // { noseY, lShoulderY, rShoulderY }
        let isCalibrated = false;
        // Metrics & Timers
        let totalFrames = 0;
        let goodFrames = 0;
        let startTime = null;
        let timerInterval = null;
        let chartInterval = null;
        let chartData = [];
        // Audio Logic
        let audioEnabled = false;
        let lastSpeakTime = 0;
        let speechSynthesis = window.speechSynthesis;
        let audioCooldown = 10000; // 10 seconds between alerts
        // Local Storage Init
        let savedHighScore = localStorage.getItem('posture_high_score') || 0;
        highScoreDisplay.innerText = `${savedHighScore}%`;
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-cyan-400' : (type === 'error' ? 'text-red-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        window.toggleAudio = function () {
            audioEnabled = !audioEnabled;
            if (audioEnabled) {
                audioToggleBtn.classList.remove('bg-slate-700');
                audioToggleBtn.classList.add('bg-cyan-500');
                audioKnob.classList.add('translate-x-6');
                log("Audio Alerts: ENABLED");
                speak("Audio alerts enabled.");
            } else {
                audioToggleBtn.classList.add('bg-slate-700');
                audioToggleBtn.classList.remove('bg-cyan-500');
                audioKnob.classList.remove('translate-x-6');
                log("Audio Alerts: DISABLED");
            }
        };
        function speak(text) {
            if (!audioEnabled || !speechSynthesis) return;
            const now = Date.now();
            if (now - lastSpeakTime < audioCooldown) return;
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.rate = 1.1;
            utterance.pitch = 1.0;
            utterance.volume = 0.5;
            speechSynthesis.speak(utterance);
            lastSpeakTime = now;
        }
        async function createPoseLandmarker() {
            log("Initializing MediaPipe Pose V2...");
            try {
                const filesetResolver = await FilesetResolver.forVisionTasks(
                    "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
                );
                poseLandmarker = await PoseLandmarker.createFromOptions(filesetResolver, {
                    baseOptions: {
                        modelAssetPath: `https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task`,
                        delegate: "GPU"
                    },
                    runningMode: runningMode,
                    numPoses: 1
                });
                log("Vision Core Ready. Tracking Engine Standby.", "success");
            } catch (e) {
                log("LOAD ERROR: Vision nodes failed to sync.", "error");
            }
        }
        window.startWebcam = async function () {
            if (!poseLandmarker) {
                log("Loading AI pose models on demand...", "default");
                await createPoseLandmarker();
            }
            try {
                log("Requesting optical stream...");
                stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } });
                video.srcObject = stream;
                document.getElementById('cam-btn').classList.add('hidden');
                // Wait for video load
                video.onloadeddata = () => {
                    video.style.display = 'block';
                    statusText.style.display = 'none';
                    faceGuide.style.display = 'block';
                    liveIndicator.style.display = 'block';
                    resultBadge.style.display = 'block';
                    calibrateBtn.disabled = false;
                    trackingActive = true;
                    log("Stream active. Skeleton analysis engaged.", "success");
                    document.getElementById('tracking-status').innerText = "ACTIVE";
                    document.getElementById('tracking-status').className = "text-cyan-500 font-bold uppercase";
                    predictWebcam();
                };
            } catch (err) {
                console.error(err);
                log("HARDWARE ERROR: Permission denied.", "error");
            }
        };
        window.calibratePose = function () {
            if (!results || !results.landmarks || results.landmarks.length === 0) {
                log("CALIBRATION ERROR: No subject detected.", "error");
                return;
            }
            const lm = results.landmarks[0];
            // Nose: 0, Left Shoulder: 11, Right Shoulder: 12
            baseline = {
                noseY: lm[0].y,
                lShoulderY: lm[11].y,
                rShoulderY: lm[12].y,
                avgShoulderY: (lm[11].y + lm[12].y) / 2
            };
            isCalibrated = true;
            totalFrames = 0;
            goodFrames = 0;
            startTime = Date.now();
            // Start Timers
            if (timerInterval) clearInterval(timerInterval);
            timerInterval = setInterval(updateTimer, 1000);
            // Start Charting
            if (chartInterval) clearInterval(chartInterval);
            chartInterval = setInterval(updateChart, 2000); // Add bar every 2 secs
            chartData = [];
            chartContainer.innerHTML = '';
            log("Baseline Set. Posture Monitoring Active.", "success");
            document.getElementById('status-val').innerText = "GOOD";
            document.getElementById('status-val').className = "text-4xl font-black mb-4 tracking-tighter text-green-500";
        };
        window.resetSystem = function () {
            isCalibrated = false;
            baseline = null;
            alertOverlay.style.display = 'none';
            if (timerInterval) clearInterval(timerInterval);
            if (chartInterval) clearInterval(chartInterval);
            document.getElementById('status-val').innerText = "CALIBRATE";
            document.getElementById('status-val').className = "text-4xl font-black mb-4 tracking-tighter";
            document.getElementById('dev-val').innerText = "--px";
            timerDisplay.innerText = "00:00";
            chartContainer.innerHTML = '';
            log("System Reset. Please recalibrate.");
        };
        function updateTimer() {
            const delta = Math.floor((Date.now() - startTime) / 1000);
            const m = Math.floor(delta / 60).toString().padStart(2, '0');
            const s = (delta % 60).toString().padStart(2, '0');
            timerDisplay.innerText = `${m}:${s}`;
        }
        function updateChart() {
            if (!isCalibrated) return;
            const quality = totalFrames > 0 ? (goodFrames / totalFrames) * 100 : 100;
            // Create Bar
            const bar = document.createElement('div');
            bar.className = 'chart-bar';
            // Height proportional to quality (min 10% for visibility)
            bar.style.height = `${Math.max(10, quality)}%`;
            // Color based on quality
            if (quality > 85) bar.style.backgroundColor = '#22d3ee'; // cyan
            else if (quality > 60) bar.style.backgroundColor = '#facc15'; // yellow
            else bar.style.backgroundColor = '#ef4444'; // red
            chartContainer.appendChild(bar);
            // Keep max 50 bars
            if (chartContainer.children.length > 50) {
                chartContainer.removeChild(chartContainer.firstChild);
            }
            graphStat.innerText = `${quality.toFixed(0)}% AVG`;
        }
        async function predictWebcam() {
            if (!trackingActive) return;
            // Ensure video has valid dimensions
            if (video.videoWidth === 0 || video.videoHeight === 0) {
                requestAnimationFrame(predictWebcam);
                return;
            }
            let startTimeMs = performance.now();
            if (lastVideoTime !== video.currentTime) {
                lastVideoTime = video.currentTime;
                if (poseLandmarker) {
                    results = poseLandmarker.detectForVideo(video, startTimeMs);
                }
            }
            canvas.width = video.clientWidth;
            canvas.height = video.clientHeight;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            if (results && results.landmarks && results.landmarks.length > 0) {
                const landmarks = results.landmarks[0];
                document.getElementById('points-val').innerText = "33 Pts";
                drawSkeleton(landmarks);
                if (isCalibrated) {
                    processPosture(landmarks);
                } else {
                    // Prompt user to calibrate
                    ctx.font = "bold 16px Inter";
                    ctx.fillStyle = "rgba(255,255,255,0.8)";
                    ctx.textAlign = "center";
                    ctx.fillText("SIT STRAIGHT & CLICK CALIBRATE", canvas.width / 2, canvas.height / 2 + 100);
                }
            } else {
                if (trackingActive) {
                    // Draw searching rect
                    ctx.strokeStyle = "rgba(255,255,255,0.2)";
                    ctx.lineWidth = 2;
                    ctx.strokeRect(canvas.width / 2 - 100, canvas.height / 2 - 100, 200, 200);
                    ctx.font = "12px monospace";
                    ctx.fillStyle = "white";
                    ctx.fillText("SEARCHING...", canvas.width / 2 - 35, canvas.height / 2);
                }
            }
            requestAnimationFrame(predictWebcam);
        }
        function drawSkeleton(landmarks) {
            ctx.fillStyle = '#22d3ee'; // Cyan
            ctx.strokeStyle = 'rgba(34, 211, 238, 0.5)';
            ctx.lineWidth = 2;
            // Draw Key Points: Nose (0), Ears (7,8), Shoulders (11,12)
            const indices = [0, 7, 8, 11, 12];
            indices.forEach(i => {
                const p = landmarks[i];
                ctx.beginPath();
                ctx.arc(p.x * canvas.width, p.y * canvas.height, 4, 0, 2 * Math.PI);
                ctx.fill();
            });
            // Connect Shoulders
            ctx.beginPath();
            ctx.moveTo(landmarks[11].x * canvas.width, landmarks[11].y * canvas.height);
            ctx.lineTo(landmarks[12].x * canvas.width, landmarks[12].y * canvas.height);
            ctx.stroke();
            // Connect Nose to Shoulders (Visual Triangle)
            ctx.beginPath();
            ctx.moveTo(landmarks[0].x * canvas.width, landmarks[0].y * canvas.height);
            ctx.lineTo(landmarks[11].x * canvas.width, landmarks[11].y * canvas.height);
            ctx.moveTo(landmarks[0].x * canvas.width, landmarks[0].y * canvas.height);
            ctx.lineTo(landmarks[12].x * canvas.width, landmarks[12].y * canvas.height);
            ctx.stroke();
        }
        function processPosture(lm) {
            totalFrames++;
            // Current Metrics
            const currentNoseY = lm[0].y;
            const currentAvgShoulderY = (lm[11].y + lm[12].y) / 2;
            // 1. Calculate Spine Deviation (Slouching)
            const deviationY = (currentAvgShoulderY - baseline.avgShoulderY);
            const deviationPx = (deviationY * canvas.height).toFixed(0);
            document.getElementById('dev-val').innerText = `${deviationPx > 0 ? '+' : ''}${deviationPx}px`;
            // 2. Shoulder Tilt
            const tilt = Math.abs(lm[11].y - lm[12].y) * 100; // rough factor
            document.getElementById('tilt-val').innerText = `${tilt.toFixed(1)}°`;
            // 3. Neck Position (Text Neck)
            const noseDrop = currentNoseY - baseline.noseY;
            const shoulderDrop = currentAvgShoulderY - baseline.avgShoulderY;
            const neckFlexion = noseDrop - shoulderDrop;
            let status = "GOOD";
            let color = "text-green-500";
            let neckStatus = "Neutral";
            let isBad = false;
            // Thresholds (Tunable based on normalized coordinates)
            if (deviationY > 0.05) {
                status = "SLOUCHING";
                color = "text-red-500";
                isBad = true;
                speak("Posture check. You are slouching.");
            } else if (neckFlexion > 0.03) {
                status = "TEXT NECK";
                color = "text-orange-500";
                neckStatus = "Forward";
                isBad = true;
                speak("Head up. Check your neck.");
            } else if (tilt > 5) {
                status = "LEANING";
                color = "text-yellow-500";
                isBad = true;
                speak("Shoulders are uneven.");
            }
            if (!isBad) {
                goodFrames++;
                neckStatus = "Aligned";
                alertOverlay.style.display = 'none';
            } else {
                alertOverlay.style.display = 'block';
            }
            document.getElementById('status-val').innerText = status;
            document.getElementById('status-val').className = `text-4xl font-black mb-4 tracking-tighter ${color}`;
            document.getElementById('neck-val').innerText = neckStatus;
            // Quality Score Logic
            const quality = ((goodFrames / totalFrames) * 100).toFixed(0);
            document.getElementById('quality-val').innerText = `${quality}%`;
            // Save High Score
            if (totalFrames > 100 && parseInt(quality) > parseInt(savedHighScore)) {
                savedHighScore = quality;
                localStorage.setItem('posture_high_score', savedHighScore);
                highScoreDisplay.innerText = `${savedHighScore}%`;
            }
        }

        log("Posture Guard Pro Node initialized.");
